+		side_axis[(p_cylinder_axis + 1) % 3] = 1.0f; // Any side axis OK.
+		axis_dir = side_axis;
+	} else {
+		axis_dir = crs / crs_l;
+	}
+
+	real_t dist = axis_dir.dot(p_from);
+
+	if (dist >= p_radius) {
+		return false; // Too far away.
+	}
+
+	// Convert to 2D.
+	real_t w2 = p_radius * p_radius - dist * dist;
