+real_t Geometry2D::get_closest_points_between_segments(const Vector2 &p_p1, const Vector2 &p_q1, const Vector2 &p_p2, const Vector2 &p_q2, Vector2 &p_c1, Vector2 &p_c2) {
+	Vector2 d1 = p_q1 - p_p1; // Direction vector of segment S1.
+	Vector2 d2 = p_q2 - p_p2; // Direction vector of segment S2.
+	Vector2 r = p_p1 - p_p2;
+	real_t a = d1.dot(d1); // Squared length of segment S1, always nonnegative.
+	real_t e = d2.dot(d2); // Squared length of segment S2, always nonnegative.
+	real_t f = d2.dot(r);
+	real_t s, t;
+	// Check if either or both segments degenerate into points.
+	if (a <= (real_t)CMP_EPSILON && e <= (real_t)CMP_EPSILON) {
+		// Both segments degenerate into points.
+		p_c1 = p_p1;
+		p_c2 = p_p2;
+		return Math::sqrt((p_c1 - p_c2).dot(p_c1 - p_c2));
+	}
+	if (a <= (real_t)CMP_EPSILON) {
+		// First segment degenerates into a point.
+		s = 0.0;
+		t = f / e; // s = 0 => t = (b*s + f) / e = f / e
+		t = CLAMP(t, 0.0f, 1.0f);
+	} else {
+		real_t c = d1.dot(r);
+		if (e <= (real_t)CMP_EPSILON) {
+			// Second segment degenerates into a point.
+			t = 0.0;
+			s = CLAMP(-c / a, 0.0f, 1.0f); // t = 0 => s = (b*t - c) / a = -c / a
+		} else {
+			// The general nondegenerate case starts here.
+			real_t b = d1.dot(d2);
+			real_t denom = a * e - b * b; // Always nonnegative.
+			// If segments not parallel, compute closest point on L1 to L2 and
+			// clamp to segment S1. Else pick arbitrary s (here 0).
+			if (denom != 0.0f) {
+				s = CLAMP((b * f - c * e) / denom, 0.0f, 1.0f);
+			} else {
+				s = 0.0;
+			}
+			// Compute point on L2 closest to S1(s) using
+			// t = Dot((p_p1 + D1*s) - p_p2,D2) / Dot(D2,D2) = (b*s + f) / e
+			t = (b * s + f) / e;
+
+			//If t in [0,1] done. Else clamp t, recompute s for the new value
+			// of t using s = Dot((p_p2 + D2*t) - p_p1,D1) / Dot(D1,D1)= (t*b - c) / a
+			// and clamp s to [0, 1].
+			if (t < 0.0f) {
+				t = 0.0;
+				s = CLAMP(-c / a, 0.0f, 1.0f);
+			} else if (t > 1.0f) {
+				t = 1.0;
+				s = CLAMP((b - c) / a, 0.0f, 1.0f);
+			}
+		}
+	}
+	p_c1 = p_p1 + d1 * s;
+	p_c2 = p_p2 + d2 * t;
+	return Math::sqrt((p_c1 - p_c2).dot(p_c1 - p_c2));
+}
