+bool Geometry2D::is_point_in_triangle(const Vector2 &p_s, const Vector2 &p_a, const Vector2 &p_b, const Vector2 &p_c) {
+	Vector2 an = p_a - p_s;
+	Vector2 bn = p_b - p_s;
+	Vector2 cn = p_c - p_s;
+
+	bool orientation = an.cross(bn) > 0;
+
+	if ((bn.cross(cn) > 0) != orientation) {
+		return false;
+	}
+
+	return (cn.cross(an) > 0) == orientation;
