+bool Geometry2D::is_polygon_clockwise(const Vector<Vector2> &p_polygon) {
+	int c = p_polygon.size();
+	if (c < 3) {
+		return false;
+	}
+	const Vector2 *p = p_polygon.ptr();
+	real_t sum = 0;
+	for (int i = 0; i < c; i++) {
+		const Vector2 &v1 = p[i];
+		const Vector2 &v2 = p[(i + 1) % c];
+		sum += (v2.x - v1.x) * (v2.y + v1.y);
+	}
+
+	return sum > 0.0f;
+}
