+	int intersections = 0;
+	for (int i = 0; i < c; i++) {
+		const Vector2 &v1 = p[i];
+		const Vector2 &v2 = p[(i + 1) % c];
+
+		Vector2 res;
+		if (segment_intersects_segment(v1, v2, p_point, further_away, &res)) {
