+bool Geometry3D::segment_intersects_sphere(const Vector3 &p_from, const Vector3 &p_to, const Vector3 &p_sphere_pos, real_t p_sphere_radius, Vector3 *r_res, Vector3 *r_norm) {
+	Vector3 sphere_pos = p_sphere_pos - p_from;
