+
+	// Check in segment.
+	if (inters_d < 0 || inters_d > rel_l) {
+		return false;
+	}
+
+	Vector3 result = p_from + normal * inters_d;
+
+	if (r_res) {
+		*r_res = result;
+	}
+	if (r_norm) {
+		*r_norm = (result - p_sphere_pos).normalized();
