+bool Geometry3D::ray_intersects_triangle(const Vector3 &p_from, const Vector3 &p_dir, const Vector3 &p_v0, const Vector3 &p_v1, const Vector3 &p_v2, Vector3 *r_res) {
+	Vector3 e1 = p_v1 - p_v0;
+	Vector3 e2 = p_v2 - p_v0;
+	Vector3 h = p_dir.cross(e2);
+	real_t a = e1.dot(h);
+	if (Math::is_zero_approx(a)) { // Parallel test.
+		return false;
+	}
+
+	real_t f = 1.0f / a;
+
+	Vector3 s = p_from - p_v0;
+	real_t u = f * s.dot(h);
+
+	if ((u < 0.0f) || (u > 1.0f)) {
+		return false;
+	}
+
+	Vector3 q = s.cross(e1);
+
+	real_t v = f * p_dir.dot(q);
+
+	if ((v < 0.0f) || (u + v > 1.0f)) {
+		return false;
+	}
+
+	// At this stage we can compute t to find out where
+	// the intersection point is on the line.
+	real_t t = f * e2.dot(q);
+
+	if (t > 0.00001f) { // ray intersection
+		if (r_res) {
+			*r_res = p_from + p_dir * t;
+		}
+		return true;
+	} else { // This means that there is a line intersection but not a ray intersection.
+		return false;
+	}
+}
+
+bool Geometry3D::segment_intersects_triangle(const Vector3 &p_from, const Vector3 &p_to, const Vector3 &p_v0, const Vector3 &p_v1, const Vector3 &p_v2, Vector3 *r_res) {
+	Vector3 rel = p_to - p_from;
+	Vector3 e1 = p_v1 - p_v0;
+	Vector3 e2 = p_v2 - p_v0;
+	Vector3 h = rel.cross(e2);
+	real_t a = e1.dot(h);
+	if (Math::is_zero_approx(a)) { // Parallel test.
+		return false;
+	}
+
+	real_t f = 1.0f / a;
+
+	Vector3 s = p_from - p_v0;
+	real_t u = f * s.dot(h);
+
+	if ((u < 0.0f) || (u > 1.0f)) {
+		return false;
+	}
+
+	Vector3 q = s.cross(e1);
+
+	real_t v = f * rel.dot(q);
+
+	if ((v < 0.0f) || (u + v > 1.0f)) {
+		return false;
+	}
+
+	// At this stage we can compute t to find out where
+	// the intersection point is on the line.
+	real_t t = f * e2.dot(q);
+
+	if (t > (real_t)CMP_EPSILON && t <= 1.0f) { // Ray intersection.
+		if (r_res) {
+			*r_res = p_from + rel * t;
+		}
+		return true;
+	} else { // This means that there is a line intersection but not a ray intersection.
+		return false;
+	}
+}
