+bool Geometry3D::planeBoxOverlap(Vector3 p_normal, real_t p_d, Vector3 p_max_box) {
+	int q;
+	Vector3 vmin, vmax;
+	for (q = 0; q <= 2; q++) {
+		if (p_normal[q] > 0.0f) {
+			vmin[q] = -p_max_box[q];
+			vmax[q] = p_max_box[q];
+		} else {
+			vmin[q] = p_max_box[q];
+			vmax[q] = -p_max_box[q];
+		}
+	}
+	if (p_normal.dot(vmin) + p_d > 0.0f) {
+		return false;
+	}
+	if (p_normal.dot(vmax) + p_d >= 0.0f) {
+		return true;
+	}
+
+	return false;
+}
